const productsRaw = $input.first().json;
const products = Array.isArray(productsRaw) ? productsRaw : [];

const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

// Find rejected products older than 30 days
const toDelete = products.filter(p => {
  return p.status === 'rejected' && new Date(p.created_at) < thirtyDaysAgo;
});

// Find pending products stuck for 7+ days
const sevenDaysAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
const stuckPending = products.filter(p => {
  return p.status === 'pending' && new Date(p.created_at) < sevenDaysAgo;
});

return [{ json: { toDelete, stuckPending, deleteCount: toDelete.length, stuckCount: stuckPending.length } }];

